pub fn nodes_copied_x(mut from: Array<kayak_rt::data::DataAt<'static, Node>>, mut to: Array<kayak_rt::data::DataAt<'static, Node>>, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_gt_eq(i, n) {
            return ();
        } else {
            array_set_x(to, i64_to_int(i), array_ref(from, i64_to_int(i)));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

pub fn armxs_copied_x(mut from: Array<kayak_rt::data::DataAt<'static, Armx>>, mut to: Array<kayak_rt::data::DataAt<'static, Armx>>, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_gt_eq(i, n) {
            return ();
        } else {
            array_set_x(to, i64_to_int(i), array_ref(from, i64_to_int(i)));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

pub fn words_copied_x(mut from: FlatArray<i64>, mut to: FlatArray<i64>, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_gt_eq(i, n) {
            return ();
        } else {
            flatarray_set_i64_x(to, i, flatarray_ref_i64(from, i));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

pub fn strings_copied_x(mut from: Array<Str>, mut to: Array<Str>, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_gt_eq(i, n) {
            return ();
        } else {
            array_set_x(to, i64_to_int(i), array_ref(from, i64_to_int(i)));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

pub fn add_node_x(x: kayak_rt::data::DataAt<'static, Node>) -> i64 {
    let n = get(node_count());
    if i64_gt_eq(n, int_to_i64(array_length(get(nodes())))) {
        let (bigger, os, ws) = (the::<Array<kayak_rt::data::DataAt<'static, Node>>>(make_array(i64_to_int(i64_star(n, 2i64)), n_lit(0i64))), the::<FlatArray<i64>>(make_flatarray_i64(i64_star(n, 2i64), -1i64)), the::<Array<Str>>(make_array(i64_to_int(i64_star(n, 2i64)), str_lit!(""))));
        nodes_copied_x(get(nodes()), bigger, 0i64, n);
        set(nodes(), bigger);
        words_copied_x(get(owners()), os, 0i64, n);
        set(owners(), os);
        strings_copied_x(get(wheres()), ws, 0i64, n);
        set(wheres(), ws)
    } else {
        ()
    };
    array_set_x(get(nodes()), i64_to_int(n), x);
    set(node_count(), i64_plus(n, 1i64));
    n
}

pub fn add_kid_x(k: i64) -> i64 {
    let n = get(kid_count());
    if i64_gt_eq(n, flatarray_length_i64(get(kids()))) {
        let bigger = the::<FlatArray<i64>>(make_flatarray_i64(i64_star(n, 2i64), 0i64));
        words_copied_x(get(kids()), bigger, 0i64, n);
        set(kids(), bigger)
    } else {
        ()
    };
    flatarray_set_i64_x(get(kids()), n, k);
    set(kid_count(), i64_plus(n, 1i64));
    n
}

pub fn add_armx_x(a: kayak_rt::data::DataAt<'static, Armx>) -> i64 {
    let n = get(armx_count());
    if i64_gt_eq(n, int_to_i64(array_length(get(armxs())))) {
        let bigger = the::<Array<kayak_rt::data::DataAt<'static, Armx>>>(make_array(i64_to_int(i64_star(n, 2i64)), armx(0i64, 0i64, 0i64)));
        armxs_copied_x(get(armxs()), bigger, 0i64, n);
        set(armxs(), bigger)
    } else {
        ()
    };
    array_set_x(get(armxs()), i64_to_int(n), a);
    set(armx_count(), i64_plus(n, 1i64));
    n
}

pub fn add_constant_x(w: i64) -> i64 {
    let n = get(constant_count());
    if i64_gt_eq(n, flatarray_length_i64(get(constants()))) {
        let bigger = the::<FlatArray<i64>>(make_flatarray_i64(i64_star(n, 2i64), 0i64));
        words_copied_x(get(constants()), bigger, 0i64, n);
        set(constants(), bigger)
    } else {
        ()
    };
    flatarray_set_i64_x(get(constants()), n, w);
    set(constant_count(), i64_plus(n, 1i64));
    n
}

/// The nodes from `i` to `end` that no inner lambda has, `l`'s.
pub fn owned_x(mut i: i64, mut end: i64, mut l: i64) -> () {
    loop {
        if i64_gt_eq(i, end) {
            return ();
        } else {
            if i64_lt(flatarray_ref_i64(get(owners()), i), 0i64) {
                flatarray_set_i64_x(get(owners()), i, l)
            } else {
                ()
            };
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

// A node's lambda's backtrace words, or "" outside every lambda.
pub fn node_where(i: i64) -> Str {
    if (i64_lt(i, 0i64) || i64_gt_eq(i, get(node_count()))) {
        str_lit!("")
    } else {
        let l = flatarray_ref_i64(get(owners()), i);
        if i64_lt(l, 0i64) {
            str_lit!("")
        } else {
            array_ref(get(wheres()), i64_to_int(l))
        }
    }
}

// A node's lambda's number, or -1.
#[inline]
pub fn node_owner(i: i64) -> i64 {
    if (i64_lt(i, 0i64) || i64_gt_eq(i, get(node_count()))) {
        -1i64
    } else {
        flatarray_ref_i64(get(owners()), i)
    }
}

#[inline]
pub fn node_at(i: i64) -> kayak_rt::data::DataAt<'static, Node> {
    array_ref(get(nodes()), i64_to_int(i))
}

#[inline]
pub fn kid_at(i: i64) -> i64 {
    flatarray_ref_i64(get(kids()), i)
}

#[inline]
pub fn armx_at(i: i64) -> kayak_rt::data::DataAt<'static, Armx> {
    array_ref(get(armxs()), i64_to_int(i))
}

#[inline]
pub fn constant_at(i: i64) -> i64 {
    flatarray_ref_i64(get(constants()), i)
}

